content:
{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "SSM session actions are granted against all resources",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "HIGH",
      "explanation": "The policy permits starting sessions on any accessible managed EC2 instance and resuming or terminating any SSM session. This can provide remote shell access to unintended instances and interfere with other users' sessions."
    }
  ],
  "patched_code": "variable "ssm_target_instance_arns" {
  description = "Specific EC2 instance ARNs on which this policy may start SSM sessions."
  type        = list(string)

  validation {
    condition = length(var.ssm_target_instance_arns) > 0 && alltrue([
      for arn in var.ssm_target_instance_arns :
      can(regex("^arn:[^:]+:ec2:[^:]+:[0-9]{12}:instance/i-[0-9a-fA-F]+$", arn))
    ])
    error_message = "ssm_target_instance_arns must contain one or more specific EC2 instance ARNs."
  }
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "ssm:StartSession"
        Resource = var.ssm_target_instance_arns
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:session/$${aws:username}-*"
      }
    ]
  })
}
